package io.reactivex.rxjava3.internal.operators.observable;

import java.util.Objects;
import java.util.concurrent.atomic.*;

import io.reactivex.rxjava3.core.*;
import io.reactivex.rxjava3.disposables.Disposable;
import io.reactivex.rxjava3.exceptions.CompositeException;
import io.reactivex.rxjava3.exceptions.Exceptions;
import io.reactivex.rxjava3.functions.Function;
import io.reactivex.rxjava3.internal.disposables.DisposableHelper;
import io.reactivex.rxjava3.internal.util.AtomicThrowable;
import io.reactivex.rxjava3.internal.util.ExceptionHelper;
import io.reactivex.rxjava3.operators.QueueDisposable;
import io.reactivex.rxjava3.operators.SimpleQueue;
import io.reactivex.rxjava3.operators.SpscLinkedArrayQueue;
import io.reactivex.rxjava3.plugins.RxJavaPlugins;

public final class ObservableSwitchMap<T, R> extends AbstractObservableWithUpstream<T, R> {
    final Function<? super T, ? extends ObservableSource<? extends R>> mapper;
    final int bufferSize;

    final boolean delayErrors;

    public ObservableSwitchMap(ObservableSource<T> source,
                               Function<? super T, ? extends ObservableSource<? extends R>> mapper, int bufferSize,
                                       boolean delayErrors) {
        super(source);
        this.mapper = mapper;
        this.bufferSize = bufferSize;
        this.delayErrors = delayErrors;
    }

    @Override
    public void subscribeActual(Observer<? super R> t) {

        if (ObservableScalarXMap.tryScalarXMapSubscribe(source, t, mapper)) {
            return;
        }

        source.subscribe(new SwitchMapObserver<>(t, mapper, bufferSize, delayErrors));
    }

    static final class SwitchMapObserver<T, R> extends AtomicInteger implements Observer<T>, Disposable {

        private static final long serialVersionUID = -3491074160481096299L;
        final Observer<? super R> downstream;
        final Function<? super T, ? extends ObservableSource<? extends R>> mapper;
        final int bufferSize;

        final boolean delayErrors;

        final AtomicThrowable errors;

        volatile boolean done;

        volatile boolean cancelled;

        Disposable upstream;

        final AtomicReference<SwitchMapInnerObserver<T, R>> active = new AtomicReference<>();

        static final SwitchMapInnerObserver<Object, Object> CANCELLED;
        static {
            CANCELLED = new SwitchMapInnerObserver<>(null, -1L, 1);
            CANCELLED.cancel();
        }

        volatile long unique;

        SwitchMapObserver(Observer<? super R> actual,
                Function<? super T, ? extends ObservableSource<? extends R>> mapper, int bufferSize,
                        boolean delayErrors) {
            this.downstream = actual;
            this.mapper = mapper;
            this.bufferSize = bufferSize;
            this.delayErrors = delayErrors;
            this.errors = new AtomicThrowable();
        }

        @Override
        public void onSubscribe(Disposable d) {
            if (DisposableHelper.validate(this.upstream, d)) {
                this.upstream = d;
                downstream.onSubscribe(this);
            }
        }

        @Override
        public void onNext(T t) {
            long c = unique + 1;
            unique = c;

            SwitchMapInnerObserver<T, R> inner = active.get();
            if (inner != null) {
                inner.cancel();
            }

            ObservableSource<? extends R> p;
            try {
                p = Objects.requireNonNull(mapper.apply(t), "The ObservableSource returned is null");
            } catch (Throwable e) {
                Exceptions.throwIfFatal(e);
                upstream.dispose();
                onError(e);
                return;
            }

            SwitchMapInnerObserver<T, R> nextInner = new SwitchMapInnerObserver<>(this, c, bufferSize);

            for (;;) {
                inner = active.get();
                if (inner == CANCELLED) {
                    break;
                }
                if (active.compareAndSet(inner, nextInner)) {
                    p.subscribe(nextInner);
                    break;
                }
            }
        }

        @Override
        public void onError(Throwable t) {
            if (!done && errors.tryAddThrowable(t)) {
                if (!delayErrors) {
                    disposeInner();
                }
                done = true;
                drain();
            } else {
                RxJavaPlugins.onError(t);
            }
        }

        @Override
        public void onComplete() {
            if (!done) {
                done = true;
                drain();
            }
        }

        @Override
        public void dispose() {
            if (!cancelled) {
                cancelled = true;
                upstream.dispose();
                disposeInner();

                errors.tryTerminateAndReport();
            }
        }

        @Override
        public boolean isDisposed() {
            return cancelled;
        }

        @SuppressWarnings("unchecked")
        void disposeInner() {
            SwitchMapInnerObserver<T, R> a = active.getAndSet((SwitchMapInnerObserver<T, R>)CANCELLED);
            if (a != null) {
                a.cancel();
            }
        }

        void drain() {
            if (getAndIncrement() != 0) {
                return;
            }

            final Observer<? super R> a = downstream;
            final AtomicReference<SwitchMapInnerObserver<T, R>> active = this.active;
            final boolean delayErrors = this.delayErrors;

            int missing = 1;

            for (;;) {

                if (cancelled) {
                    return;
                }

                if (done) {
                    boolean empty = active.get() == null;
                    if (delayErrors) {
                        if (empty) {
                            Throwable ex = errors.get();
                            if (ex != null) {
                                a.onError(ex);
                            } else {
                                a.onComplete();
                            }
                            return;
                        }
                    } else {
                        Throwable ex = errors.get();
                        if (ex != null) {
                            errors.tryTerminateConsumer(a);
                            return;
                        }
                        if (empty) {
                            a.onComplete();
                            return;
                        }
                    }
                }

                SwitchMapInnerObserver<T, R> inner = active.get();

                if (inner != null) {
                    SimpleQueue<R> q = inner.queue;

                    if (q != null) {

                        boolean retry = false;

                        for (;;) {
                            if (cancelled) {
                                return;
                            }
                            if (inner != active.get()) {
                                retry = true;
                                break;
                            }

                            if (!delayErrors) {
                                Throwable ex = errors.get();
                                if (ex != null) {
                                    errors.tryTerminateConsumer(a);
                                    return;
                                }
                            }

                            boolean d = inner.done;
                            R v;

                            try {
                                v = q.poll();
                            } catch (Throwable ex) {
                                Exceptions.throwIfFatal(ex);
                                errors.tryAddThrowableOrReport(ex);
                                active.compareAndSet(inner, null);
                                if (!delayErrors) {
                                    disposeInner();
                                    upstream.dispose();
                                    done = true;
                                } else {
                                    inner.cancel();
                                }
                                v = null;
                                retry = true;
                            }
                            boolean empty = v == null;

                            if (d && empty) {
                                active.compareAndSet(inner, null);
                                retry = true;
                                break;
                            }

                            if (empty) {
                                break;
                            }

                            a.onNext(v);
                        }

                        if (retry) {
                            continue;
                        }
                    }
                }

                missing = addAndGet(-missing);
                if (missing == 0) {
                    break;
                }
            }
        }

        void innerError(SwitchMapInnerObserver<T, R> inner, Throwable ex) {
            if (inner.index == unique && errors.tryAddThrowable(ex)) {
                if (!delayErrors) {
                    upstream.dispose();
                    done = true;
                }
                inner.done = true;
                drain();
            } else {
                RxJavaPlugins.onError(ex);
            }
        }
    }

    static final class SwitchMapInnerObserver<T, R> extends AtomicReference<Disposable> implements Observer<R> {

        private static final long serialVersionUID = 3837284832786408377L;
        final SwitchMapObserver<T, R> parent;
        final long index;

        final int bufferSize;

        volatile SimpleQueue<R> queue;

        volatile boolean done;

        SwitchMapInnerObserver(SwitchMapObserver<T, R> parent, long index, int bufferSize) {
            this.parent = parent;
            this.index = index;
            this.bufferSize = bufferSize;
        }

        @Override
        public void onSubscribe(Disposable d) {
            if (DisposableHelper.setOnce(this, d)) {
                if (d instanceof QueueDisposable) {
                    @SuppressWarnings("unchecked")
                    QueueDisposable<R> qd = (QueueDisposable<R>) d;

                    int m = qd.requestFusion(QueueDisposable.ANY | QueueDisposable.BOUNDARY);
                    if (m == QueueDisposable.SYNC) {
                        queue = qd;
                        done = true;
                        parent.drain();
                        return;
                    }
                    if (m == QueueDisposable.ASYNC) {
                        queue = qd;
                        return;
                    }
                }

                queue = new SpscLinkedArrayQueue<>(bufferSize);
            }
        }

        @Override
        public void onNext(R t) {
            final SwitchMapObserver<T, R> observer = parent;
            final long generation = index;
            if (generation != observer.unique) {
                return;
            }
            if (t != null) {
                queue.offer(t);
            }
            int outstanding = observer.getAndIncrement();
            if (outstanding != 0) {
                return;
            }

            final Observer<? super R> downstreamObserver = observer.downstream;
            final AtomicReference<SwitchMapInnerObserver<T, R>> active = observer.active;
            final boolean delayErrors = observer.delayErrors;
            final AtomicThrowable errors = observer.errors;
            final Disposable upstream = observer.upstream;
            final Throwable terminatedMarker = ExceptionHelper.TERMINATED;
            int missing = 1;

            for (;;) {
                boolean cancelled = observer.cancelled;
                if (cancelled) {
                    return;
                }

                boolean mainDone = observer.done;
                if (mainDone) {
                    SwitchMapInnerObserver<T, R> currentInner = active.get();
                    boolean empty = currentInner == null;
                    if (delayErrors) {
                        if (empty) {
                            Throwable ex = errors.get();
                            if (ex != null) {
                                downstreamObserver.onError(ex);
                            } else {
                                downstreamObserver.onComplete();
                            }
                            return;
                        }
                    } else {
                        Throwable ex = errors.get();
                        if (ex != null) {
                            Throwable terminated = errors.get();
                            if (terminated != terminatedMarker) {
                                terminated = errors.getAndSet(terminatedMarker);
                            }
                            if (terminated == null) {
                                downstreamObserver.onComplete();
                            } else if (terminated != terminatedMarker) {
                                downstreamObserver.onError(terminated);
                            }
                            return;
                        }
                        if (empty) {
                            downstreamObserver.onComplete();
                            return;
                        }
                    }
                }

                SwitchMapInnerObserver<T, R> inner = active.get();
                SimpleQueue<R> innerQueue = null;
                boolean innerIsActive = inner != null;
                if (innerIsActive) {
                    innerQueue = inner.queue;
                }
                boolean queueMissing = innerQueue == null;
                boolean skipInner = inner == null || queueMissing;
                if (!skipInner) {
                    boolean retry = false;
                    for (;;) {
                        cancelled = observer.cancelled;
                        if (cancelled) {
                            return;
                        }
                        SwitchMapInnerObserver<T, R> latest = active.get();
                        if (inner != latest) {
                            retry = true;
                            break;
                        }

                        if (!delayErrors) {
                            Throwable ex = errors.get();
                            if (ex != null) {
                                errors.tryTerminateConsumer(downstreamObserver);
                                return;
                            }
                        }

                        boolean innerDone = inner.done;
                        boolean innerCompleted = innerDone;
                        R v;
                        R polled = null;
                        try {
                            polled = innerQueue.poll();
                            v = polled;
                        } catch (Throwable ex) {
                            if (ex instanceof VirtualMachineError) {
                                throw (VirtualMachineError) ex;
                            } else if (ex instanceof ThreadDeath) {
                                throw (ThreadDeath) ex;
                            } else if (ex instanceof LinkageError) {
                                throw (LinkageError) ex;
                            }
                            boolean added = false;
                            Throwable aggregated = ex;
                            for (;;) {
                                Throwable current = errors.get();
                                if (current == terminatedMarker) {
                                    break;
                                } else {
                                    Throwable update;
                                    if (current == null) {
                                        update = aggregated;
                                    } else {
                                        update = new CompositeException(current, aggregated);
                                    }
                                    if (errors.compareAndSet(current, update)) {
                                        added = true;
                                        break;
                                    }
                                }
                            }
                            if (!added) {
                                Throwable undeliverable = aggregated;
                                RxJavaPlugins.onError(undeliverable);
                            }
                            active.compareAndSet(inner, null);
                            if (!delayErrors) {
                                observer.disposeInner();
                                Disposable upstreamDisposable = upstream;
                                upstreamDisposable.dispose();
                                observer.done = true;
                            } else {
                                inner.cancel();
                            }
                            v = null;
                            retry = true;
                        }
                        boolean empty = v == null;
                        if (innerCompleted && empty) {
                            active.compareAndSet(inner, null);
                            retry = true;
                            break;
                        }
                        if (empty) {
                            break;
                        }
                        downstreamObserver.onNext(v);
                    }
                    if (retry) {
                        continue;
                    }
                }

                int wip = missing;
                missing = observer.addAndGet(-wip);
                if (missing == 0) {
                    break;
                }
            }
        }

        @Override
        public void onError(Throwable t) {
            parent.innerError(this, t);
        }

        @Override
        public void onComplete() {
            if (index == parent.unique) {
                done = true;
                parent.drain();
            }
        }

        public void cancel() {
            DisposableHelper.dispose(this);
        }
    }
}

